function categoryPriceScope(p,rule){if(categoriesEnabled()&&rule.canonical_category_id){const id=p.canonical_category_id||p.last_confirmed_category_id,base=canonicalPath(rule.canonical_category_id),current=canonicalPath(id);return !!base&&(id===rule.canonical_category_id||current.startsWith(base+' / '));}return norm(rule.value)===norm(financialCategory(p));}
const canonicalLegacyReadPrices=readPrices;readPrices=function(){canonicalLegacyReadPrices();if(!categoriesEnabled()||!S.priceDraft)return;for(const rule of S.priceDraft.rules||[]){if(rule.scope!=='category'){delete rule.canonical_category_id;continue;}const previous=(S.cfg.rules||[]).find(r=>r.scope==='category'&&r.value===rule.value);if(previous&&!rule.canonical_category_id)continue;const id=canonicalCategories().find(c=>canonicalPath(c.id)===rule.value)?.id;if(id)rule.canonical_category_id=id;else delete rule.canonical_category_id;}};
